// CUDA C++, sm_80 (A100)
__global__ void transpose(const float* __restrict__ A, float* __restrict__ B, int N) {
    __shared__ float tile[32][32];    // 32 x 32 floats, 4 B each; 32 SMEM banks of 4 B
    int x = blockIdx.x * 32 + threadIdx.x;
    int y = blockIdx.y * 32 + threadIdx.y;

    tile[threadIdx.y][threadIdx.x] = A[y * N + x];       // (W1) write
    __syncthreads();

    int tx = blockIdx.y * 32 + threadIdx.x;
    int ty = blockIdx.x * 32 + threadIdx.y;
    B[ty * N + tx] = tile[threadIdx.x][threadIdx.y];     // (R1) transposed read
}
